1	package gateway
2	
3	import (
4		"fmt"
5		"path"
6		"strings"
7	
8		"github.com/nogo/wire/internal/config"
9	)
10	
11	// routeTable maps model aliases to backend names.
12	type routeTable struct {
13		aliases        map[string]string   // alias → backend name
14		backendAliases map[string][]string // backend name → all its aliases
15	}
16	
17	// buildRouteTable constructs the route table from config.
18	func buildRouteTable(cfg *config.Config) *routeTable {
19		rt := &routeTable{
20			aliases:        make(map[string]string),
21			backendAliases: make(map[string][]string),
22		}
23		for name, b := range cfg.Backends {
24			aliases := []string{name}
25			if b.IsManaged() && b.Model != "" {
26				aliases = append(aliases, modelAliases(b.Model)...)
27			}
28			rt.backendAliases[name] = aliases
29			for _, alias := range aliases {
30				if _, exists := rt.aliases[alias]; !exists {
31					rt.aliases[alias] = name
32				}
33			}
34		}
35		return rt
36	}
37	
38	// resolve returns the backend name for the given model string.
39	func (rt *routeTable) resolve(model string) (string, error) {
40		if name, ok := rt.aliases[model]; ok {
41			return name, nil
42		}
43		return "", fmt.Errorf("unknown model %q", model)
44	}
45	
46	// modelAliases returns all routing aliases for a HuggingFace model ref.
47	//
48	// For "Qwen/Qwen3-Coder-30B-A3B-Instruct-GGUF:Q4_K_M" this produces:
49	//   - "Qwen/Qwen3-Coder-30B-A3B-Instruct-GGUF:Q4_K_M"  (full ref)
50	//   - "Qwen3-Coder-30B-A3B-Instruct-GGUF"              (repo name)
51	//   - "Qwen3-Coder-30B-A3B-Instruct-Q4_K_M"            (filename stem — what llama-server reports)
52	//   - "Qwen3-Coder-30B-A3B-Instruct"                   (short form without GGUF/quantization)
53	func modelAliases(hfRef string) []string {
54		aliases := []string{hfRef}
55	
56		repoPath, quant, _ := strings.Cut(hfRef, ":")
57		repoName := path.Base(repoPath)
58		if repoName != "" && repoName != "." {
59			aliases = append(aliases, repoName)
60		}
61	
62		// Strip the -GGUF suffix to get the model base name.
63		baseName := strings.TrimSuffix(repoName, "-GGUF")
64		baseName = strings.TrimSuffix(baseName, "-gguf")
65	
66		if quant != "" {
67			// This is the filename stem llama-server sets as the model name.
68			aliases = append(aliases, baseName+"-"+quant)
69		}
70	
71		if baseName != "" && baseName != repoName {
72			aliases = append(aliases, baseName)
73		}
74	
75		return aliases
76	}
77	
