226	func contains(s, sub string) bool {
227		return len(s) >= len(sub) && (s == sub || len(sub) == 0 ||
228			func() bool {
229				for i := range len(s) - len(sub) + 1 {
230					if s[i:i+len(sub)] == sub {
231						return true
232					}
233				}
234				return false
235			}())
236	}
