1	package monitor
2	
3	import (
4		"context"
5		"encoding/json"
6		"net/http"
7		"time"
8	
9		"nhooyr.io/websocket"
10	)
11	
12	// HandleWS returns an HTTP handler that upgrades to WebSocket and streams hub
13	// messages as JSON. It sends a snapshot on connect, then forwards all
14	// subsequent hub messages until the client disconnects or the hub stops.
15	func HandleWS(hub *Hub) http.HandlerFunc {
16		return func(w http.ResponseWriter, r *http.Request) {
17			conn, err := websocket.Accept(w, r, &websocket.AcceptOptions{
18				InsecureSkipVerify: true,
19			})
20			if err != nil {
21				return
22			}
23			defer conn.CloseNow()
24	
25			ctx, cancel := context.WithCancel(r.Context())
26			defer cancel()
27	
28			// Subscribe before reading the snapshot so no events are lost between
29			// the two operations.
30			ch, unsub := hub.Subscribe()
31			defer unsub()
32	
33			// Drain the initial MsgSnapshot that Subscribe pushes to the channel.
34			var hubSnap *HubSnapshot
35			select {
36			case msg := <-ch:
37				if msg.Snap != nil {
38					hubSnap = msg.Snap
39				}
40			case <-time.After(time.Second):
41			}
42			if hubSnap == nil {
43				s := hub.Snapshot()
44				hubSnap = &s
45			}
46	
47			// Send the snapshot as the first wire message.
48			snap := buildSnapshotMsg(hubSnap, hub.Statuses())
49			if err := writeJSON(ctx, conn, snap); err != nil {
50				return
51			}
52	
53			// Discard goroutine: reads from the client only to detect close frames
54			// and network drops. Cancels ctx so the main loop exits.
55			go func() {
56				defer cancel()
57				for {
58					if _, _, err := conn.Read(ctx); err != nil {
59						return
60					}
61				}
62			}()
63	
64			// Stream hub messages.
65			for {
66				select {
67				case <-ctx.Done():
68					return
69				case msg, ok := <-ch:
70					if !ok {
71						// Hub was stopped.
72						conn.Close(websocket.StatusGoingAway, "server stopping")
73						return
74					}
75					out := toWireMsg(msg)
76					if out == nil {
77						continue
78					}
79					wCtx, wCancel := context.WithTimeout(ctx, 10*time.Second)
80					writeErr := writeJSON(wCtx, conn, out)
81					wCancel()
82					if writeErr != nil {
83						return
84					}
85				}
86			}
87		}
88	}
89	
90	func writeJSON(ctx context.Context, conn *websocket.Conn, v any) error {
91		data, err := json.Marshal(v)
92		if err != nil {
93			return err
94		}
95		return conn.Write(ctx, websocket.MessageText, data)
96	}
97	
98	// snapMsg is the initial state snapshot sent on connect.
99	type snapMsg struct {
100		Type     string                     `json:"type"`
101		Backends map[string]backendSnapInfo `json:"backends"`
102		GPUs     []GPUMetrics               `json:"gpus"`
103	}
104	
105	type backendSnapInfo struct {
106		Model     string  `json:"model"`
107		Status    string  `json:"status"`
108		PID       int     `json:"pid"`
109		Port      int     `json:"port"`
110		UptimeSec float64 `json:"uptime_sec"`
111		Restarts  int     `json:"restarts"`
112	}
113	
114	func buildSnapshotMsg(snap *HubSnapshot, statuses []BackendStatus) snapMsg {
115		backends := make(map[string]backendSnapInfo, len(statuses))
116		for _, s := range statuses {
117			status := "unhealthy"
118			if s.Healthy {
119				status = "healthy"
120			}
121			uptime := 0.0
122			if !s.StartedAt.IsZero() {
123				uptime = time.Since(s.StartedAt).Seconds()
124			}
125			backends[s.Name] = backendSnapInfo{
126				Model:     s.Model,
127				Status:    status,
128				PID:       s.PID,
129				Port:      s.Port,
130				UptimeSec: uptime,
131				Restarts:  s.Restarts,
132			}
133		}
134		gpus := snap.GPUs
135		if gpus == nil {
136			gpus = []GPUMetrics{}
137		}
138		return snapMsg{Type: "snapshot", Backends: backends, GPUs: gpus}
139	}
140	
141	// gpuWireMsg is the periodic GPU metrics update.
142	type gpuWireMsg struct {
143		Type string       `json:"type"`
144		GPUs []GPUMetrics `json:"gpus"`
145	}
146	
147	// metricsWireMsg is the periodic per-backend metrics update.
148	type metricsWireMsg struct {
149		Type       string          `json:"type"`
150		Backend    string          `json:"backend"`
151		KVCachePct float64         `json:"kv_cache_pct"`
152		SlotsBusy  int             `json:"slots_busy"`
153		SlotsTotal int             `json:"slots_total"`
154		QueueDepth int             `json:"queue_depth"`
155		GenTokS    float64         `json:"gen_tok_s"`
156		PromptTokS float64         `json:"prompt_tok_s"`
157		Slots      []slotWireEntry `json:"slots"`
158	}
159	
160	type slotWireEntry struct {
161		ID      int    `json:"id"`
162		State   string `json:"state"`
163		Tokens  int    `json:"tokens"`
164		CtxUsed int    `json:"ctx_used"`
165	}
166	
167	// eventWireMsg is a structured server event.
168	type eventWireMsg struct {
169		Type       string  `json:"type"`
170		Backend    string  `json:"backend"`
171		Kind       string  `json:"kind"`
172		Slot       int     `json:"slot"`
173		Tokens     int     `json:"tokens"`
174		TokS       float64 `json:"tok_s"`
175		DurationMs float64 `json:"duration_ms"`
176		Message    string  `json:"message"`
177	}
178	
179	// stateWireMsg is a backend health state transition.
180	type stateWireMsg struct {
181		Type    string `json:"type"`
182		Backend string `json:"backend"`
183		Status  string `json:"status"`
184		Model   string `json:"model"`
185	}
186	
187	// toWireMsg converts a HubMessage to the JSON-serialisable wire type.
188	// Returns nil for message kinds that have no wire representation.
189	func toWireMsg(msg HubMessage) any {
190		switch msg.Kind {
191		case MsgGPUTick:
192			gpus := msg.GPUs
193			if gpus == nil {
194				gpus = []GPUMetrics{}
195			}
196			return gpuWireMsg{Type: "gpu", GPUs: gpus}
197	
198		case MsgMetricsTick:
199			if msg.Metrics == nil {
200				return nil
201			}
202			m := msg.Metrics
203			slotsBusy := 0
204			slots := make([]slotWireEntry, 0, len(m.Slots))
205			for _, s := range m.Slots {
206				state := "idle"
207				if s.State == SlotProcessing {
208					state = "generating"
209					slotsBusy++
210				}
211				slots = append(slots, slotWireEntry{
212					ID:      s.ID,
213					State:   state,
214					Tokens:  s.TokensPredicted,
215					CtxUsed: s.TokensEvaluated,
216				})
217			}
218			return metricsWireMsg{
219				Type:       "metrics",
220				Backend:    m.Name,
221				KVCachePct: m.KVCacheUsageRatio * 100,
222				SlotsBusy:  slotsBusy,
223				SlotsTotal: len(m.Slots),
224				QueueDepth: m.RequestsPending,
225				GenTokS:    m.TokensPerSecond,
226				PromptTokS: m.PromptTokensPerSecond,
227				Slots:      slots,
228			}
229	
230		case MsgServerEvent:
231			if msg.Event == nil {
232				return nil
233			}
234			e := msg.Event
235			return eventWireMsg{
236				Type:       "event",
237				Backend:    e.Backend,
238				Kind:       eventKindStr(e.Kind),
239				Slot:       e.Slot,
240				Tokens:     e.Tokens,
241				TokS:       e.TokPerSec,
242				DurationMs: e.DurationMs,
243				Message:    e.Message,
244			}
245	
246		case MsgStateChange:
247			status := "unhealthy"
248			if msg.Healthy {
249				status = "healthy"
250			}
251			return stateWireMsg{
252				Type:    "state",
253				Backend: msg.Backend,
254				Status:  status,
255			}
256	
257		default:
258			return nil
259		}
260	}
261	
262	func eventKindStr(k EventKind) string {
263		switch k {
264		case EventSlotAssign:
265			return "slot_assign"
266		case EventSlotRelease:
267			return "slot_release"
268		case EventPromptEval:
269			return "prompt_eval"
270		case EventGenEval:
271			return "gen_eval"
272		case EventModelLoad:
273			return "model_load"
274		case EventVRAMAlloc:
275			return "vram_alloc"
276		case EventError:
277			return "error"
278		case EventRaw:
279			return "raw"
280		default:
281			return "unknown"
282		}
283	}
