1	package config
2	
3	import (
4		"bytes"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9	
10		"gopkg.in/yaml.v3"
11	)
12	
13	// Path returns the resolved config file path.
14	// Resolution order: WIRE_CONFIG env var → XDG_CONFIG_HOME/wire/config.yaml →
15	// ~/.config/wire/config.yaml.
16	func Path() string {
17		if v := os.Getenv("WIRE_CONFIG"); v != "" {
18			return v
19		}
20		base := os.Getenv("XDG_CONFIG_HOME")
21		if base == "" {
22			home, _ := os.UserHomeDir()
23			base = filepath.Join(home, ".config")
24		}
25		return filepath.Join(base, "wire", "config.yaml")
26	}
27	
28	// WriteFile marshals cfg to YAML and atomically replaces the config file.
29	func WriteFile(cfg *Config) error {
30		path := Path()
31		data, err := yaml.Marshal(cfg)
32		if err != nil {
33			return fmt.Errorf("marshaling config: %w", err)
34		}
35		tmp := path + ".tmp"
36		if err := os.WriteFile(tmp, data, 0644); err != nil {
37			return fmt.Errorf("writing config temp file: %w", err)
38		}
39		if err := os.Rename(tmp, path); err != nil {
40			os.Remove(tmp)
41			return fmt.Errorf("renaming config file: %w", err)
42		}
43		return nil
44	}
45	
46	type Config struct {
47		Listen   string             `yaml:"listen"`
48		Backends map[string]Backend `yaml:"backends"`
49		Peers    []string           `yaml:"peers"`
50		Monitor  bool               `yaml:"monitor"`
51	}
52	
53	type Backend struct {
54		// Managed backend (llama-server)
55		Model     string   `yaml:"model"`      // HuggingFace ref, e.g. "Qwen/Qwen3-Coder-30B-A3B-Instruct-GGUF:Q4_K_M"
56		Context   int      `yaml:"context"`    // Context window size
57		GPULayers int      `yaml:"gpu_layers"` // -ngl flag
58		Pooling   string   `yaml:"pooling"`    // "mean", "cls", "rank" — triggers --embedding flag
59		Extra     []string `yaml:"extra"`      // Additional llama-server flags
60	
61		// External backend (Ollama, OpenAI, Anthropic, etc.)
62		URL      string `yaml:"url"`      // If set, backend is external — no process management
63		APIKey   string `yaml:"api_key"`  // Bearer token or x-api-key
64		Provider string `yaml:"provider"` // "openai" (default) or "anthropic"
65	}
66	
67	// IsManaged reports whether wire manages the llama-server process for this backend.
68	func (b Backend) IsManaged() bool { return b.URL == "" }
69	
70	// IsExternal reports whether this backend is an external service.
71	func (b Backend) IsExternal() bool { return !b.IsManaged() }
72	
73	// ValidationError describes a config validation failure.
74	type ValidationError struct {
75		Field   string
76		Message string
77	}
78	
79	func (e *ValidationError) Error() string {
80		return fmt.Sprintf("config validation: %s: %s", e.Field, e.Message)
81	}
82	
83	// Load reads the config from disk, applies defaults, and validates it.
84	// Path resolution order: WIRE_CONFIG env var → XDG_CONFIG_HOME/wire/config.yaml →
85	// ~/.config/wire/config.yaml.
86	func Load() (*Config, error) {
87		path := Path()
88	
89		data, err := os.ReadFile(path)
90		if err != nil {
91			if errors.Is(err, os.ErrNotExist) {
92				return nil, fmt.Errorf("config file not found at %s: %w", path, err)
93			}
94			return nil, fmt.Errorf("reading config %s: %w", path, err)
