1	package process
2	
3	import (
4		"context"
5		"fmt"
6		"log/slog"
7		"net/http"
8		"net/http/httptest"
9		"os"
10		"os/exec"
11		"os/signal"
12		"syscall"
13		"testing"
14		"time"
15	
16		"github.com/nogo/wire/internal/config"
17	)
18	
19	// ---------------------------------------------------------------------------
20	// Subprocess helper: fake llama-server
21	//
22	// Tests that need a real process invoke the test binary itself with
23	// GO_WANT_HELPER_PROCESS=1 and -test.run=TestHelperProcess.
24	// The subprocess then acts as a minimal llama-server on the requested port.
25	// ---------------------------------------------------------------------------
26	
27	// TestHelperProcess is NOT a real test — it is a subprocess target.
28	func TestHelperProcess(t *testing.T) {
29		if os.Getenv("GO_WANT_HELPER_PROCESS") != "1" {
30			return
31		}
32	
33		// Locate args after "--"
34		args := os.Args
35		for i, a := range args {
36			if a == "--" {
37				args = args[i+1:]
38				break
39			}
40		}
41	
42		if len(args) == 0 || args[0] != "llama-server" {
43			fmt.Fprintln(os.Stderr, "expected llama-server as first arg")
44			os.Exit(2)
45		}
46	
47		// Parse --port from remaining flags.
48		port := "8080"
49		for i, a := range args[1:] {
50			if a == "--port" && i+1 < len(args[1:]) {
51				port = args[1:][i+1]
52			}
53		}
54	
55		mux := http.NewServeMux()
56		mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
57			w.WriteHeader(http.StatusOK)
58		})
59	
60		srv := &http.Server{Addr: ":" + port, Handler: mux}
61		go srv.ListenAndServe() //nolint:errcheck
62	
63		sigCh := make(chan os.Signal, 1)
64		signal.Notify(sigCh, syscall.SIGTERM, syscall.SIGINT)
65		<-sigCh
66	
67		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
68		defer cancel()
69		srv.Shutdown(ctx) //nolint:errcheck
70		os.Exit(0)
71	}
72	
73	// testCmdBuilder returns a cmdBuilder that runs the test binary as a fake
74	// llama-server subprocess.
75	func testCmdBuilder(ctx context.Context, b config.Backend, port int) *exec.Cmd {
76		args := append(
77			[]string{"-test.run=TestHelperProcess", "--", "llama-server"},
78			buildArgs(b, port)...,
79		)
80		cmd := exec.CommandContext(ctx, os.Args[0], args...)
81		cmd.Env = append(os.Environ(), "GO_WANT_HELPER_PROCESS=1")
82		return cmd
83	}
84	
85	// newTestManager creates a Manager wired to the fake llama-server subprocess.
86	func newTestManager(cfg *config.Config) *Manager {
87		m := New(cfg, slog.Default())
88		m.cmdBuilder = testCmdBuilder
89		return m
90	}
91	
92	// ---------------------------------------------------------------------------
93	// Unit tests — pure functions
94	// ---------------------------------------------------------------------------
95	
96	func TestBuildArgs_minimal(t *testing.T) {
97		b := config.Backend{Model: "org/model"}
98		got := buildArgs(b, 19100)
99		want := []string{"-hf", "org/model", "--port", "19100", "--no-webui"}
100		if fmt.Sprint(got) != fmt.Sprint(want) {
101			t.Errorf("buildArgs minimal: got %v, want %v", got, want)
102		}
103	}
104	
105	func TestBuildArgs_full(t *testing.T) {
106		b := config.Backend{
107			Model:     "org/model",
108			GPULayers: 32,
109			Context:   4096,
110			Pooling:   "mean",
111			Extra:     []string{"--flash-attn"},
112		}
113		got := buildArgs(b, 19101)
114		want := []string{
115			"-hf", "org/model",
116			"--port", "19101",
117			"--no-webui",
118			"-ngl", "32",
119			"-c", "4096",
120			"--embedding", "--pooling", "mean",
121			"--flash-attn",
122		}
123		if fmt.Sprint(got) != fmt.Sprint(want) {
124			t.Errorf("buildArgs full: got %v, want %v", got, want)
125		}
126	}
127	
128	func TestBuildArgs_zeroGPULayersOmitted(t *testing.T) {
129		b := config.Backend{Model: "org/model", GPULayers: 0, Context: 0}
130		args := buildArgs(b, 19102)
131		for _, a := range args {
132			if a == "-ngl" || a == "-c" {
133				t.Errorf("unexpected flag %q in args: %v", a, args)
134			}
135		}
136	}
137	
138	func TestFreePort(t *testing.T) {
139		port, err := freePort()
140		if err != nil {
141			t.Fatalf("freePort: %v", err)
142		}
143		if port <= 0 || port > 65535 {
144			t.Errorf("freePort returned out-of-range port: %d", port)
145		}
146	}
147	
148	// ---------------------------------------------------------------------------
149	// External backend tests
