// ---------------------------------------------------------------------------

func TestManager_AddrExternal(t *testing.T) {
	cfg := &config.Config{
		Backends: map[string]config.Backend{
			"ext": {URL: "http://api.example.com", Provider: "openai"},
		},
	}
	m := New(cfg, slog.Default())

