// ---- integration test -------------------------------------------------------

type mockManager struct {
	addr string
}

func (m *mockManager) Addr(_ string) (string, bool) { return m.addr, true }
func (m *mockManager) Healthy(_ string) bool        { return true }

func TestIntegration_SameSystemPrompt_SameSlot(t *testing.T) {
	var (
		mu       sync.Mutex
		received [][]byte
	)

	// Backend captures proxied request bodies.
	backend := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		mu.Lock()
		received = append(received, body)
		mu.Unlock()
		w.Header().Set("Content-Type", "application/json")
		fmt.Fprint(w, `{"id":"t","object":"chat.completion","model":"test","choices":[]}`)
	}))
	defer backend.Close()

	cfg := &config.Config{
		Listen: ":0",
		Backends: map[string]config.Backend{
			"test": {Model: "test/model", Slots: 2, Provider: "openai"},
		},
	}

	gw := newGateway(cfg, &mockManager{addr: backend.URL}, nil, slog.Default())
	gwServer := httptest.NewServer(gw.server.Handler)
	defer gwServer.Close()

	reqBody := `{"model":"test","messages":[{"role":"system","content":"You are a test assistant."},{"role":"user","content":"Hello"}]}`

	sendRequest := func() {
		t.Helper()
		resp, err := http.Post(gwServer.URL+"/v1/chat/completions", "application/json", strings.NewReader(reqBody))
		if err != nil {
			t.Fatalf("request failed: %v", err)
		}
		resp.Body.Close()
	}

	sendRequest()
	sendRequest()

	mu.Lock()
	defer mu.Unlock()

	if len(received) != 2 {
		t.Fatalf("backend received %d requests, want 2", len(received))
	}

	extractSlot := func(body []byte) (int, bool) {
		var p struct {
			IDSlot *int `json:"id_slot"`
		}
		if err := json.Unmarshal(body, &p); err != nil || p.IDSlot == nil {
			return -1, false
		}
		return *p.IDSlot, true
	}

	slot1, ok1 := extractSlot(received[0])
	slot2, ok2 := extractSlot(received[1])

	if !ok1 || !ok2 {
		t.Fatalf("id_slot missing from proxied body: req1=%q req2=%q", received[0], received[1])
	}
	if slot1 != slot2 {
		t.Errorf("same system prompt should route to same slot: got %d and %d", slot1, slot2)
	}
}

func TestIntegration_Fallback_NoSlotOnHashZero(t *testing.T) {
	var (
		mu       sync.Mutex
		received []byte
	)

	backend := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		mu.Lock()
		received = body
		mu.Unlock()
		w.Header().Set("Content-Type", "application/json")
		fmt.Fprint(w, `{"id":"t","object":"chat.completion","model":"test","choices":[]}`)
	}))
	defer backend.Close()

	cfg := &config.Config{
		Listen: ":0",
		Backends: map[string]config.Backend{
			"test": {Model: "test/model", Slots: 2, Provider: "openai"},
		},
	}

	gw := newGateway(cfg, &mockManager{addr: backend.URL}, nil, slog.Default())
	gwServer := httptest.NewServer(gw.server.Handler)
	defer gwServer.Close()

	// Empty messages → hash=0 → no id_slot injected.
	reqBody := `{"model":"test","messages":[]}`
	resp, err := http.Post(gwServer.URL+"/v1/chat/completions", "application/json", strings.NewReader(reqBody))
	if err != nil {
		t.Fatalf("request failed: %v", err)
	}
	resp.Body.Close()

	mu.Lock()
	defer mu.Unlock()

	var p struct {
		IDSlot *int `json:"id_slot"`
	}
	json.Unmarshal(received, &p) //nolint:errcheck
	if p.IDSlot != nil {
		t.Errorf("empty messages should not inject id_slot, got %d", *p.IDSlot)
	}
}

